 "content": "from collections import deque, Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen, comps = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx)); q.append((ny,nx))
            comps.append((color, cells))

    # Detect the elbow key: orthogonal one-cell-thick L; its open quadrant
    # points from the corner away from the two arms.
    keys = []
    for color, cells in comps:
        ss = set(cells)
        for y, x in cells:
            ds = {(dy,dx) for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)) if (y+dy,x+dx) in ss}
            if len(ds) == 2 and {d[0] for d in ds} != {0} and {d[1] for d in ds} != {0}:
                vertical = next(d[0] for d in ds if d[0])
                horizontal = next(d[1] for d in ds if d[1])
                keys.append((len(cells), color, y, x, -vertical, -horizontal))
    if not keys:
        return [row[:] for row in grid]
    _, key, cy, cx, sy, sx = max(keys)

    # Objects positioned in the elbow's inside quadrant are selected; in
    # these puzzles it is the closest such component to the corner.
    candidates = []
    for color, cells in comps:
        if color == key:
            continue
        cy_obj = sum(y for y,x in cells)/len(cells)
        cx_obj = sum(x for y,x in cells)/len(cells)
        dy, dx = cy_obj-cy, cx_obj-cx
        penalty = (0 if dy == 0 or (dy > 0) == (sy > 0) else 100) + (0 if dx == 0 or (dx > 0) == (sx > 0) else 100)
        distance = min(abs(y-cy)+abs(x-cx) for y,x in cells)
        candidates.append((penalty+distance, color, cells))
    if not candidates:
        return [row[:] for row in grid]
    _, _, target = min(candidates, key=lambda v:v[0])
    result = [row[:] for row in grid]
    for y,x in target:
        result[y][x] = key
