def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen, comps = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            comps.append((color, cells))

    # Find the most pronounced orthogonal elbow component (the guide).
    keys = []
    for color, cells in comps:
        ss = set(cells)
        for y, x in cells:
            for vy, hx in ((-1, 1), (-1, -1), (1, 1), (1, -1)):
                if (y + vy, x) not in ss or (y, x + hx) not in ss:
                    continue
                a = 0
                while (y + (a + 1) * vy, x) in ss:
                    a += 1
                b = 0
                while (y, x + (b + 1) * hx) in ss:
                    b += 1
                # The interior/open quadrant is opposite the two arms.
                keys.append((a + b, min(a, b), color, y, x, -vy, -hx, len(cells)))
    if not keys:
        return [row[:] for row in grid]
    _, _, key, cy, cx, sy, sx, _ = max(keys)

    # The target is the closest distinct object in the open quadrant of the elbow.
    candidates = []
    for color, cells in comps:
        if color == key:
            continue
        distances = []
        for y, x in cells:
            dy, dx = y - cy, x - cx
            wrong = (dy != 0 and (dy > 0) != (sy > 0)) or (dx != 0 and (dx > 0) != (sx > 0))
            distances.append((abs(dy) + abs(dx) + (100 if wrong else 0), abs(dy) + abs(dx)))
        score, dist = min(distances)
        candidates.append((score, dist, color, cells))
    if not candidates:
        return [row[:] for row in grid]
    _, _, _, target = min(candidates, key=lambda z: (z[0], z[1]))
    out = [row[:] for row in grid]
    for y, x in target:
        out[y][x] = key
    return out
